<template>
  <div class="cp-form back-white">

    <div class="row q-col-gutter-sm">
      <div class="col-6">
        <div class="cp-field">
          <label class="cp-label">{{ $t('date_pattern') }}</label>
          <q-select
            dense
            outlined
            options-dense
            class="input-sm"
            v-model="org_based_settings[date_pattern]"
            :options="date_pattern_list"
            emit-value
            map-options
            data-cy="date_pattern"
            data-test="company-date-pattern-select"
          />
        </div>
      </div>
      <div class="col-6">
        <div class="cp-field">
          <label class="cp-label">{{ $t('amount_format') }}</label>
          <q-select
            dense
            outlined
            options-dense
            class="input-sm"
            v-model="org_based_settings[amounts_locale]"
            :options="format_origins"
            emit-value
            map-options
            data-cy="amount_format"
            data-test="company-amount-format-select"
          />
        </div>
      </div>
    </div>

    <!-- Display Settings -->
    <div class="cp-subsection">
      <div class="cp-field">
        <f-toggle size="xs"
          v-model="org_based_settings[version_info_dialog]"
          :label="$t('new_version_info_dialog')"
        />
      </div>
    </div>

    <!-- Save Button -->
    <div class="cp-footer">
      <q-btn
        unelevated
        :label="$t('save')"
        color="primary"
        @click="save_org"
        size="md"
        data-test="company-preference-save-btn"
      />
    </div>
  </div>
  <Loader />
</template>
<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import {
  version_info_dialog,
  date_pattern_setting,
  amount_format_setting,
} from 'src/constants';
import {
  useDatePatternDropdownStore,
  useLangOriginDropdownStore,
  useSettingStore,
} from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    Loader,
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  data() {
    return {
      date_pattern: date_pattern_setting,
      amounts_locale: amount_format_setting,
      version_info_dialog: version_info_dialog,
    };
  },
  mounted() {
    this.pupulateDefault();
    this.getDatePatternOptions();
  },
  methods: {
    initView() {
      this.pupulateDefault();
      this.companyPrefOldValus = JSON.parse(
        JSON.stringify(this.org_based_settings),
      );
    },
    async save_org() {
      try {
        this.showLoading();

        if (
          this.companyPrefOldValus[this.date_pattern] !=
          this.org_based_settings[this.date_pattern]
        ) {
          await this.updateSetting(
            this.date_pattern,
            this.org_based_settings[this.date_pattern],
          );
        }

        if (
          this.companyPrefOldValus[this.amounts_locale] !=
          this.org_based_settings[this.amounts_locale]
        ) {
          await this.updateSetting(
            this.amounts_locale,
            this.org_based_settings[this.amounts_locale],
          );
        }

        if (
          this.companyPrefOldValus[version_info_dialog] !=
          this.org_based_settings[version_info_dialog]
        ) {
          await this.updateSetting(
            version_info_dialog,
            this.org_based_settings[version_info_dialog],
          );
        }

        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    pupulateDefault() {
      if (!this.org_based_settings[this.date_pattern]) {
        this.org_based_settings[this.date_pattern] = '';
      }
      if (!this.org_based_settings[this.amounts_locale]) {
        this.org_based_settings[this.amounts_locale] = '';
      }
      if (!this.org_based_settings[version_info_dialog]) {
        this.org_based_settings[version_info_dialog] = false;
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { org_based_settings, loading_settings } =
      storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    const language_origin_dropdown = useLangOriginDropdownStore();
    const { format_origins } = storeToRefs(language_origin_dropdown);
    const date_pattern_dropdown = useDatePatternDropdownStore();
    const { date_pattern_list } = storeToRefs(date_pattern_dropdown);
    const { getDatePatternOptions } = date_pattern_dropdown;
    return {
      org_based_settings,
      loading_settings,
      companyPrefOldValus: ref({} as any),
      updateSetting,
      format_origins,
      date_pattern_list,
      getDatePatternOptions,
    };
  },
});
</script>

