<template>
  <div class="page-container page-height-limit">
    <div class="row q-col-gutter-md">
      <!-- Main Content (Left Column) -->
      <div :class="showHelp ? 'col-12 col-md-8' : 'col-12'">
        <div class="settings-page-content">

          <!-- Page Header -->
          <div class="company-settings-page-header">
            <h2 class="company-settings-page-title">{{ $t('company') }}</h2>
            <p class="company-settings-page-subtitle">{{ $t('company_info_short') }}</p>
          </div>

          <!-- Company Information -->
          <docbits-accordion-panel
            v-model="expandedSections.company_info"
            icon="mdi:office-building"
            :title="$t('company')"
            :subtitle="$t('company_info_short')"
            @update:modelValue="onSectionToggle('company_info', $event)"
          >
            <CompanyInformation />
          </docbits-accordion-panel>

          <!-- Company Preferences -->
          <docbits-accordion-panel
            v-model="expandedSections.preferences"
            icon="mdi:cog"
            :title="$t('preferences')"
            :subtitle="$t('preferences_short')"
            @update:modelValue="onSectionToggle('preferences', $event)"
          >
            <CompanyPreference />
          </docbits-accordion-panel>

          <!-- Company Theme -->
          <docbits-accordion-panel
            v-model="expandedSections.theme"
            icon="mdi:palette"
            :title="$t('company_theme')"
            :subtitle="$t('theme_short')"
            @update:modelValue="onSectionToggle('theme', $event)"
          >
            <CompanyTheme />
          </docbits-accordion-panel>


        </div>
      </div>

      <!-- Help Sidebar (Right Column) -->
      <div v-if="showHelp" class="col-12 col-md-4">
        <CompanySettingsHelp
          :activeSection="activeSection"
          @close="showHelp = false"
        />
      </div>

      <!-- Floating Help Button (when help hidden) -->
      <q-btn
        v-if="!showHelp"
        fab
        color="primary"
        icon="help_outline"
        class="floating-help-button"
        @click="showHelp = true"
      >
        <q-tooltip>Show Help</q-tooltip>
      </q-btn>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import CompanyTheme from 'src/pages/Settings/Components/Company/Theme.vue';
import CompanyInformation from 'src/pages/Settings/Components/Company/CompanyInformation.vue';
import CompanyPreference from 'src/pages/Settings/Components/Company/CompanyPreference.vue';
import CompanySettingsHelp from 'src/pages/Settings/Components/Company/CompanySettingsHelp.vue';

export default defineComponent({
  el: '#app',
  components: {
    CompanyTheme,
    CompanyInformation,
    CompanyPreference,
    CompanySettingsHelp,
  },
  setup() {
    const activeSection = ref<
      'company_info' | 'preferences' | 'theme' | null
    >(null);
    const showHelp = ref(true);
    const expandedSections = ref<Record<string, boolean>>({
      company_info: true,
      preferences: false,
      theme: false,
    });

    function onSectionToggle(section: string, expanded: boolean) {
      if (expanded) {
        activeSection.value = section as typeof activeSection.value;
      }
    }

    return {
      activeSection,
      showHelp,
      expandedSections,
      onSectionToggle,
    };
  },
});
</script>

